const searchModel: ModelDefinition<{
  searchResults: searchResults
}> = Model.extend({});

type SearchRegistry = Registry<
  {
    searchResult: typeof searchModel;
  },
  {
    searchResults: typeof searchModel;
  }
>;

type SearchSchema = Schema<SearchRegistry>;

// Pulled from https://stackoverflow.com/questions/2450954/how-to-randomize-shuffle-a-javascript-array
// for simplicity
/*
function shuffleArray(array: number[]) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}
*/

export default function MirageServer() {
  new Server<SearchRegistry>({
    models: {
      searchResult: searchModel
    },

    /*
    // An attempt for a more randomized Mirage DB
    // Note: Nonfunctional

    factories: {
      searchResult: Factory.extend({
        searchResults() {
          const productCount = 20;
          const randomizedProductList: productInfo[] = [];
          const randomIndexes: number[] = [];

          for (let i = 1; i <= masterList.length; i++) {
            randomIndexes.push(i);
          }

          shuffleArray(randomIndexes);

          for (let i = 0; i < productCount; i++) {
            randomizedProductList.push(masterList[randomIndexes[i]]);
          }

          const generatedResult: searchResults = resultsArr[Math.floor(Math.random() * resultsArr.length)];
          generatedResult.products = randomizedProductList;

          console.log(generatedResult);

          return generatedResult;
        }
      })
    },
    */

    routes() {
      this.namespace = "api"

      this.get("/searchResults", (schema: SearchSchema,) => {
        return schema.all('searchResult');
      })

      this.get("/searchResults/:keyword", (schema: SearchSchema, request) => {
        const keyword = request.params.keyword;
        const result = schema.findBy('searchResult', result => result.searchResults.keyword === keyword);

        if (result == null) {
          const mappedValue = (md5.array(keyword)[0] % 3) + 1;
          console.log(`keyword: ${keyword} and mappedValue: ${mappedValue}`);

          return schema.findBy('searchResult', result => Number(result.id) === mappedValue);
        } else {
          return result;
        }
      })
    },

    seeds(server: Server<SearchRegistry>) {
      server.create('searchResult', { searchResults: batteryResult });
      server.create('searchResult', { searchResults: buttonResult });
      server.create('searchResult', { searchResults: keyboardResult });
    }
  });
}